import { trackStreams, trackSummary } from "./graph.ts";
import { runner } from "./runner.ts";

export interface User {
  readonly id: string;
  readonly permissions: string[];
}
export type StreamsCell = number | "late" | "forbidden" | "none";
export interface PageRow {
  readonly track: string;
  readonly title: string;
  readonly streams: StreamsCell;
}

export async function renderPage(trackIds: string[], user: User): Promise<PageRow[]> {
  const deadline = Date.now() + 300;
  if (!user.permissions.includes("analytics")) {
    const r = await runner.read("track", trackIds, [trackSummary], { deadline });
    return trackIds.map((track) => ({
      track,
      title: r.rows.get(track)?.providers.trackSummary.rows[0]?.fields.title ?? "",
      streams: "forbidden",
    }));
  }
  const r = await runner.read("track", trackIds, [trackSummary, trackStreams], { deadline });
  return trackIds.map((track) => {
    const p = r.rows.get(track)?.providers;
    const s = p?.trackStreams;
    const streams: StreamsCell =
      s?.outcome === "found" ? (s.rows[0]?.fields.streams ?? "none") : s?.outcome === "absent" ? "none" : "late";
    return { track, title: p?.trackSummary.rows[0]?.fields.title ?? "", streams };
  });
}
